package com.secure.documentwallet;

import android.content.*;import android.graphics.Color;import android.os.Bundle;import android.text.*;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.util.*;import java.util.concurrent.*;

public class VaultSearchActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final ArrayList<JSONObject> docs=new ArrayList<>(),info=new ArrayList<>();private LinearLayout results;private TextView status;
 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}build();load();}
 private void build(){LinearLayout page=Ui.column(this);page.setBackgroundColor(Ui.BG);page.setPadding(Ui.dp(this,20),Ui.dp(this,16),Ui.dp(this,20),Ui.dp(this,24));LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView back=Ui.text(this,"‹",40,Ui.INK);back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,46),Ui.dp(this,52)));header.addView(Ui.title(this,"Search My Vault",25),new LinearLayout.LayoutParams(0,-2,1));page.addView(header);EditText query=Ui.field(this,"Search titles, tags, issuers, dates, notes or OCR text",false);query.setCompoundDrawablesWithIntrinsicBounds(android.R.drawable.ic_menu_search,0,0,0);query.setCompoundDrawablePadding(Ui.dp(this,10));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(-1,Ui.dp(this,58));qp.topMargin=Ui.dp(this,14);page.addView(query,qp);status=Ui.text(this,"Opening encrypted search index…",13,Ui.MUTED);status.setPadding(Ui.dp(this,4),Ui.dp(this,12),0,Ui.dp(this,10));page.addView(status);ScrollView scroll=new ScrollView(this);results=Ui.column(this);scroll.addView(results);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(page);query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render(s.toString());}public void afterTextChanged(Editable e){}});}
 private void load(){io.execute(()->{try{JSONArray all=new VaultRepository(this).all(),personal=new PrivateHubRepository(this).info();for(int i=0;i<all.length();i++)docs.add(all.getJSONObject(i));for(int i=0;i<personal.length();i++)info.add(personal.getJSONObject(i));runOnUiThread(()->{status.setText("Search "+docs.size()+" document"+(docs.size()==1?"":"s")+" and "+info.size()+" private information title"+(info.size()==1?"":"s"));render("");});}catch(Exception e){runOnUiThread(()->status.setText("The encrypted search index could not be opened"));}});}
 private void render(String value){results.removeAllViews();String q=value.trim().toLowerCase(Locale.ROOT);if(q.isEmpty()){hint("Type a word or date to search without exposing your vault outside this phone.");return;}int shown=0;for(JSONObject d:docs){String hay=(d.optString("title")+" "+d.optString("category")+" "+d.optString("issuer")+" "+d.optString("documentNumber")+" "+d.optString("issueDate")+" "+d.optString("expiryDate")+" "+d.optString("tags")+" "+d.optString("notes")+" "+d.optString("searchText")).toLowerCase(Locale.ROOT);if(hay.contains(q)){result(d.optString("title","Document"),d.optString("category","Document"),()->startActivity(new Intent(this,DocumentActivity.class).putExtra("id",d.optString("id"))));shown++;}}for(JSONObject item:info){String hay=(item.optString("title")+" "+item.optString("body")).toLowerCase(Locale.ROOT);if(hay.contains(q)){result(item.optString("title","Personal Information"),"Personal Information",()->startActivity(new Intent(this,PersonalInformationActivity.class)));shown++;}}if(shown==0)hint("No encrypted items match “"+value.trim()+"”.");}
 private void result(String title,String type,Runnable open){LinearLayout card=Ui.column(this);card.setPadding(Ui.dp(this,16),Ui.dp(this,13),Ui.dp(this,16),Ui.dp(this,13));card.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,16)));card.setElevation(Ui.dp(this,2));card.addView(Ui.title(this,title,16));card.addView(Ui.text(this,type,12,Ui.TEAL));card.setOnClickListener(v->open.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=Ui.dp(this,9);results.addView(card,p);}
 private void hint(String message){TextView text=Ui.text(this,message,15,Ui.MUTED);text.setGravity(Gravity.CENTER);text.setPadding(Ui.dp(this,24),Ui.dp(this,48),Ui.dp(this,24),Ui.dp(this,48));results.addView(text);}
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
